document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const i=document.getElementById("courier-service-form"),t=document.getElementById("courier-service-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=parseInt(document.getElementById("courier-count").value),r=parseFloat(document.getElementById("vehicle-cost").value),o=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("working-capital").value),d=parseInt(document.getElementById("daily-deliveries").value),c=parseFloat(document.getElementById("avg-delivery-fee").value),u=parseInt(document.getElementById("working-days").value),v=parseFloat(document.getElementById("seasonal-growth").value),p=parseFloat(document.getElementById("courier-salaries").value),g=parseFloat(document.getElementById("fuel-maintenance").value),m=parseFloat(document.getElementById("insurance-licenses").value),w=parseFloat(document.getElementById("office-expenses").value);if(a<=0||d<=0||c<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const y=r+o+l,$=a*d*u,h=$*c,b=h*(1+v/100),f=4*b+8*h,k=.1*f,I=f+k,E=I/12,B=p+g+m+w,D=12*B,F=I-D,x=F/12,P=F/I*100,S=y/F,A=F/y*100,C=I/a,L=F/(12*$),M=a*d*365;let R="info";F<0?R="warning":P>25&&(R="success");let O="info";A<20?O="warning":A>35&&(O="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🚚 Courier Service Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(y),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(x),`Margin: ${e(P)}`,R)}\n            ${s("⏱️ Payback Period",`${S.toFixed(1)} years`,`ROI: ${e(A)}`,S<=2?"success":"warning")}\n            ${s("🚴 Revenue per Courier",n(C),"Annual","info")}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Vehicle fleet (${a} couriers)</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment & technology</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & working capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Regular months (8 months × ${$} deliveries)</span>\n                  <span>${n(8*h)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Peak months (4 months × ${e(v)} growth)</span>\n                  <span>${n(4*b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (express, insurance)</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(I)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Courier wages</span>\n                  <span>${n(p)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Fuel & maintenance</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Insurance & licenses</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Office & other expenses</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(B)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>📊 Operational Metrics</h6>\n              <div class="metric-subtitle">\n                Couriers: <strong>${a} people</strong><br>\n                Deliveries/day: <strong>${d} per courier</strong><br>\n                Delivery rate: <strong>${n(c)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${F>0?"success":"warning"}">\n              <h6>💰 Delivery Efficiency</h6>\n              <div class="metric-subtitle">\n                Profit per delivery: <strong>${n(L)}</strong><br>\n                Annual deliveries: <strong>${Math.round(M).toLocaleString()}</strong><br>\n                Monthly revenue: <strong>${n(E)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${x>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Daily profit: <strong>${n(F/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>🎯 Growth Potential</h6>\n              <div class="metric-subtitle">\n                Seasonal growth: <strong>${e(v)}</strong><br>\n                Working days: <strong>${u}/month</strong><br>\n                Expansion potential: <strong>+${2*a} couriers</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${P<20?"<li>⚠️ Low profitability. Consider increasing rates or reducing operating costs.</li>":""}\n              ${c<4?"<li>💰 Low delivery rates. Add express delivery and premium services.</li>":""}\n              ${S>2?"<li>⏰ Long payback period. Increase delivery volume or optimize expenses.</li>":""}\n              ${d<25?"<li>📦 Low productivity. Optimize routes and operational processes.</li>":""}\n              ${P>30?"<li>🎉 Excellent profitability! Consider expanding your courier team.</li>":""}\n              <li>📱 Develop mobile app for orders and real-time tracking.</li>\n              <li>🤝 Secure long-term contracts with e-commerce businesses.</li>\n              <li>🚀 Add express delivery with 50-100% premium pricing.</li>\n              <li>📊 Implement GPS monitoring for route optimization.</li>\n              <li>💳 Integrate multiple payment methods for customer convenience.</li>\n              <li>⭐ Create loyalty program for repeat customers.</li>\n              <li>📈 Analyze peak hours and scale team accordingly.</li>\n              <li>🔄 Diversify services: food, documents, shopping, medical.</li>\n              <li>🌐 Partner with local businesses and online marketplaces.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.courierServiceBusinessData={"Number of Couriers":a,"Total Investment ($)":y,"Annual Revenue ($)":I,"Annual Expenses ($)":D,"Annual Profit ($)":F,"Monthly Profit ($)":x,"Profit Margin (%)":P,"Annual ROI (%)":A,"Payback Period (years)":S,"Daily Deliveries (per courier)":d,"Delivery Fee ($)":c,"Revenue per Courier ($)":C}}),window.downloadCSV=function(){if(!window.courierServiceBusinessData)return;const n=Object.entries(window.courierServiceBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="courier-service-business-plan.csv",s.click()}});